-- Diccionario enriquecido de columnas.
-- Los tipos fisicos reflejan lo compartido por el usuario. Para los NUMERIC
-- incompletos se conserva NUMERIC(?) hasta confirmar precision y escala.
-- Las definiciones de negocio no confirmadas se marcan PROPUESTO.

WITH c AS (
 SELECT nombre_tabla, nombre_columna, tipo_dato_fisico, tipo_dato_semantico,
        nombre_negocio, descripcion_negocio, sinonimos, dominio_negocio,
        concepto_negocio, es_clave, tipo_clave, tabla_referenciada,
        campo_referenciado, regla_transformacion, regla_validacion,
        sensibilidad, ejemplos_valores, sql_generation_hints, nivel_confianza
 FROM (VALUES
 ('dim_cliente','num_cte','INTEGER','IDENTIFICADOR','Numero de cliente','Identificador del cliente en el DWH. Confirmar unicidad y si es llave primaria.','["cliente","numero de cliente","id cliente"]','CLIENTES','IDENTIFICADOR_CLIENTE',TRUE,'PK',NULL,NULL,NULL,'Validar unicidad y no nulidad.','INTERNO','[]','Usar para conteos distintos y relacionar hechos solo tras validar cardinalidad.','PROPUESTO'),
 ('dim_cliente','fec_alta','DATE','DATE','Fecha de alta del cliente','Fecha en que el cliente inicio su relacion con la institucion.','["alta cliente","fecha de incorporacion","inicio de relacion"]','CLIENTES','FECHA_ALTA_CLIENTE',FALSE,NULL,NULL,NULL,NULL,'Fecha calendario valida.','INTERNO','[]','No confundir con fecha de alta de cuenta o fecha de informacion.','PROPUESTO'),
 ('dim_cliente','fec_nac','DATE','DATE','Fecha de nacimiento','Fecha de nacimiento; normalmente aplicable a personas fisicas.','["nacimiento","fecha de nacimiento","edad"]','CLIENTES','FECHA_NACIMIENTO',FALSE,NULL,NULL,NULL,'Calcular edad solo respecto a una fecha de referencia explicita.','No asumir fecha para personas morales.','CONFIDENCIAL','[]','Evitar exponer el dato completo si basta con rangos de edad.','PROPUESTO'),
 ('dim_cliente','tipo_persona','VARCHAR(10)','CATEGORIA','Tipo de persona','Clasificacion de persona fisica o moral; confirmar catalogo de valores.','["persona fisica","persona moral","tipo de cliente"]','CLIENTES','TIPO_PERSONA',FALSE,NULL,NULL,NULL,NULL,'Validar contra catalogo oficial.','INTERNO','[]','No inventar equivalencias de codigos.','PROPUESTO'),
 ('dim_cliente','genero_cte','VARCHAR(10)','CATEGORIA','Genero del cliente','Genero registrado para personas fisicas; confirmar codigos y tratamiento de no informado.','["genero","sexo registrado"]','CLIENTES','GENERO',FALSE,NULL,NULL,NULL,NULL,'Validar valores permitidos y categorias desconocidas.','CONFIDENCIAL','[]','No aplicar a personas morales salvo regla explicita.','PROPUESTO'),
 ('dim_cliente','segmento_cte','VARCHAR(20)','CATEGORIA','Segmento comercial','Segmentacion comercial del cliente. Valores mencionados como ejemplo: Masivo, Preferente, Premium y Private; validar catalogo real.','["segmento","nivel de cliente","categoria comercial"]','CLIENTES','SEGMENTO_CLIENTE',FALSE,NULL,NULL,NULL,NULL,'Usar valores oficiales; respetar acentos y codigos almacenados.','INTERNO','["Masivo","Preferente","Premium","Private"]','Filtrar por valor real del catalogo; no asumir mayusculas/minusculas.','PROPUESTO'),
 ('dim_cliente','giro_empresa','VARCHAR(30)','CATEGORIA','Giro empresarial','Actividad economica asociada a clientes persona moral.','["giro","actividad economica","sector empresarial"]','CLIENTES','GIRO_EMPRESA',FALSE,NULL,NULL,NULL,NULL,'Confirmar catalogo y codigos.','INTERNO','[]','Aplicable principalmente a personas morales.','PROPUESTO'),
 ('dim_cliente','cve_territorio','VARCHAR(255)','IDENTIFICADOR','Clave de territorio','Clave de la unidad territorial comercial.','["territorio","region comercial","clave territorial"]','ORGANIZACION','TERRITORIO',FALSE,NULL,NULL,NULL,NULL,'Relacionar con catalogo organizacional si existe.','INTERNO','[]','No inferir jerarquias territoriales sin catalogo.','PROPUESTO'),
 ('dim_cliente','cve_dir','VARCHAR(255)','IDENTIFICADOR','Clave de direccion','Clave de direccion dentro de la estructura organizacional.','["direccion","direccion regional"]','ORGANIZACION','DIRECCION',FALSE,NULL,NULL,NULL,NULL,'Relacionar con catalogo organizacional si existe.','INTERNO','[]','Confirmar si es clave descriptiva o identificador de jerarquia.','PROPUESTO'),
 ('dim_cliente','cve_subdir','VARCHAR(255)','IDENTIFICADOR','Clave de subdireccion','Clave de subdireccion dentro de la estructura organizacional.','["subdireccion"]','ORGANIZACION','SUBDIRECCION',FALSE,NULL,NULL,NULL,NULL,'Relacionar con catalogo organizacional si existe.','INTERNO','[]','Confirmar jerarquia con direccion y territorio.','PROPUESTO'),
 ('dim_cliente','cve_sucursal','INTEGER','IDENTIFICADOR','Clave de sucursal','Identificador de la sucursal asociada al cliente.','["sucursal","oficina","sucursal bancaria"]','ORGANIZACION','SUCURSAL',FALSE,NULL,NULL,NULL,NULL,'Validar existencia en catalogo de sucursales.','INTERNO','[]','No asumir que la sucursal actual es historica para todos los periodos.','PROPUESTO'),
 ('dim_cliente','cve_promotor','VARCHAR(10)','IDENTIFICADOR','Clave de promotor','Identificador del promotor o ejecutivo asociado al cliente.','["promotor","ejecutivo","asesor"]','ORGANIZACION','PROMOTOR',FALSE,NULL,NULL,NULL,NULL,'Validar existencia en catalogo de promotores.','INTERNO','[]','Confirmar si representa promotor actual o promotor al momento del hecho.','PROPUESTO'),

 ('dim_producto','cve_producto','VARCHAR(40)','IDENTIFICADOR','Clave de producto','Identificador del producto financiero.','["producto","clave producto","codigo de producto"]','PRODUCTOS','PRODUCTO',TRUE,'PK',NULL,NULL,NULL,'Validar unicidad y vigencia.','INTERNO','[]','Clave candidata para relacionar hechos; validar cardinalidad.','PROPUESTO'),
 ('dim_producto','cve_dominio','VARCHAR(20)','CATEGORIA','Clave de dominio','Clasificacion de alto nivel del producto; confirmar valores y significado.','["dominio","familia financiera"]','PRODUCTOS','DOMINIO_PRODUCTO',FALSE,NULL,NULL,NULL,NULL,'Validar contra catalogo de dominios.','INTERNO','[]','No asumir que el texto coincide con el campo dominio de las tablas de hechos.','PROPUESTO'),
 ('dim_producto','grupo_producto','VARCHAR(20)','CATEGORIA','Grupo de producto','Agrupacion comercial o funcional de productos.','["grupo","familia de producto"]','PRODUCTOS','GRUPO_PRODUCTO',FALSE,NULL,NULL,NULL,NULL,'Validar catalogo de grupos.','INTERNO','[]','Usar para agrupar solo despues de validar jerarquia.','PROPUESTO'),
 ('dim_producto','cve_subproducto','VARCHAR(40)','IDENTIFICADOR','Clave de subproducto','Identificador de subproducto asociado al producto.','["subproducto","clave subproducto"]','PRODUCTOS','SUBPRODUCTO',FALSE,NULL,NULL,NULL,NULL,'Validar catalogo y relacion con cve_producto.','INTERNO','[]','Confirmar si es atributo o llave a otra dimension.','PROPUESTO'),
 ('dim_producto','descripcion','VARCHAR(100)','TEXTO','Descripcion del producto','Descripcion legible del producto financiero.','["nombre producto","producto descripcion"]','PRODUCTOS','DESCRIPCION_PRODUCTO',FALSE,NULL,NULL,NULL,NULL,'Validar que no existan descripciones duplicadas con claves distintas.','INTERNO','[]','Preferir cve_producto para joins y descripcion para mostrar resultados.','PROPUESTO'),
 ('dim_producto','activo','BOOLEAN','BOOLEAN','Producto activo','Indica si el producto esta marcado como activo en el catalogo.','["vigente","activo comercialmente"]','PRODUCTOS','ESTATUS_PRODUCTO',FALSE,NULL,NULL,NULL,NULL,'Valores TRUE/FALSE.','INTERNO','["true","false"]','Aplicar filtro de activos solo si la pregunta lo solicita o la regla lo exige.','PROPUESTO'),

 ('dim_txn','cve_producto','VARCHAR(40)','IDENTIFICADOR','Clave de producto','Clave de producto asociada al tipo de transaccion, si aplica.','["producto asociado","clave producto"]','TRANSACCIONES','PRODUCTO_TRANSACCION',FALSE,NULL,NULL,NULL,NULL,'Validar papel de la columna y llave candidata de dim_txn.','INTERNO','[]','No asumir que cve_txn es unica sin comprobar combinacion de claves.','PROPUESTO'),
 ('dim_txn','cve_dominio','VARCHAR(20)','CATEGORIA','Clave de dominio','Dominio financiero asociado al tipo de transaccion.','["dominio"]','TRANSACCIONES','DOMINIO_TRANSACCION',FALSE,NULL,NULL,NULL,NULL,'Validar catalogo de dominios.','INTERNO','[]','Comparar con dominio de hechos solo si los catalogos son compatibles.','PROPUESTO'),
 ('dim_txn','grupo_producto','VARCHAR(20)','CATEGORIA','Grupo de producto','Grupo de producto asociado a la clasificacion de transacciones.','["grupo"]','TRANSACCIONES','GRUPO_PRODUCTO',FALSE,NULL,NULL,NULL,NULL,'Validar catalogo.','INTERNO','[]','Confirmar si es redundante con dim_producto.','PROPUESTO'),
 ('dim_txn','cve_subproducto','VARCHAR(40)','IDENTIFICADOR','Clave de subproducto','Clave de subproducto asociada al tipo de transaccion.','["subproducto"]','TRANSACCIONES','SUBPRODUCTO',FALSE,NULL,NULL,NULL,NULL,'Validar catalogo.','INTERNO','[]','Confirmar si forma parte de la llave compuesta.','PROPUESTO'),
 ('dim_txn','cve_txn','INT4','IDENTIFICADOR','Clave de transaccion','Codigo del tipo de transaccion. Unicidad simple o compuesta pendiente de validar.','["tipo de movimiento","codigo de transaccion","clave de movimiento"]','TRANSACCIONES','TIPO_TRANSACCION',FALSE,NULL,NULL,NULL,NULL,'Comprobar duplicados de cve_txn y de combinaciones con producto/dominio.','INTERNO','[]','No unir solo por cve_txn hasta validar unicidad.','PENDIENTE'),
 ('dim_txn','desc_txn','VARCHAR(100)','TEXTO','Descripcion de transaccion','Descripcion funcional del tipo de movimiento.','["tipo de movimiento","descripcion del movimiento"]','TRANSACCIONES','DESCRIPCION_TRANSACCION',FALSE,NULL,NULL,NULL,NULL,'Validar correspondencia con cve_txn.','INTERNO','[]','Preferir codigo para relacionar y descripcion para presentar.','PROPUESTO'),

 ('fact_sdos_captacoloca_m','num_cta','INT4','IDENTIFICADOR','Numero de cuenta','Identificador de la cuenta financiera.','["cuenta","numero de cuenta"]','CUENTAS','CUENTA',FALSE,NULL,NULL,NULL,NULL,'Validar si requiere combinacion con otras claves para unicidad.','CONFIDENCIAL','[]','Conteo de cuentas con COUNT(DISTINCT num_cta), sujeto a unicidad global.','PROPUESTO'),
 ('fact_sdos_captacoloca_m','num_cte','INT4','IDENTIFICADOR','Numero de cliente','Cliente titular o relacionado con la cuenta.','["cliente","numero de cliente"]','CLIENTES','CLIENTE',FALSE,'FK','dim_cliente','num_cte',NULL,'Validar integridad referencial y cardinalidad.','CONFIDENCIAL','[]','Join candidato a dim_cliente; validar que dim_cliente tenga una fila por num_cte.','PROPUESTO'),
 ('fact_sdos_captacoloca_m','cve_producto','VARCHAR(40)','IDENTIFICADOR','Clave de producto','Producto financiero de la cuenta.','["producto","clave producto"]','PRODUCTOS','PRODUCTO',FALSE,'FK','dim_producto','cve_producto',NULL,'Validar integridad referencial.','INTERNO','[]','Join candidato a dim_producto.','PROPUESTO'),
 ('fact_sdos_captacoloca_m','fec_alta','DATE','DATE','Fecha de alta de cuenta','Fecha de alta asociada al registro de cuenta; confirmar que no sea fecha de alta del cliente.','["fecha de apertura","alta de cuenta"]','CUENTAS','FECHA_ALTA_CUENTA',FALSE,NULL,NULL,NULL,NULL,'Formato de fecha ISO YYYY-MM-DD.','INTERNO','[]','No confundir con dim_cliente.fec_alta.','PENDIENTE'),
 ('fact_sdos_captacoloca_m','cve_mes_alta','INT4','PERIODO','Clave de mes de alta','Clave numerica del mes de alta; formato pendiente de confirmar.','["mes de apertura","periodo de alta"]','CUENTAS','MES_ALTA',FALSE,NULL,NULL,NULL,NULL,'Confirmar si formato AAAAMM u otro.','INTERNO','[]','No tratar como fecha hasta confirmar codificacion.','PENDIENTE'),
 ('fact_sdos_captacoloca_m','saldo_apertura','NUMERIC(?)','MONEDA','Saldo de apertura','Importe del saldo al inicio del periodo mensual.','["saldo inicial","saldo inicial mensual"]','CAPTACION_COLOCACION','SALDO_APERTURA',FALSE,NULL,NULL,NULL,NULL,'Confirmar precision, escala y moneda.','FINANCIERO','[]','Snapshot; no sumar entre meses.','PROPUESTO'),
 ('fact_sdos_captacoloca_m','saldo_mes','NUMERIC(?)','MONEDA','Saldo de cierre mensual','Importe del saldo al cierre del periodo mensual.','["saldo de cierre","saldo mensual","balance"]','CAPTACION_COLOCACION','SALDO_CIERRE',FALSE,NULL,NULL,NULL,NULL,'Confirmar precision, escala, moneda y regla de cierre.','FINANCIERO','[]','Snapshot; seleccionar un solo periodo para saldo puntual.','PROPUESTO'),
 ('fact_sdos_captacoloca_m','fec_informacion','INTEGER','FECHA','Fecha de informacion','Fecha de corte de la informacion almacenada, representada como entero AAAAMMDD.','["fecha de corte","fecha de informacion","corte"]','TIEMPO','FECHA_CORTE',FALSE,NULL,NULL,NULL,'Convertir a DATE con TO_DATE(fec_informacion::text, ''YYYYMMDD'') cuando se requieran funciones de fecha.','Validar que el valor tenga ocho digitos y sea fecha calendario valida.','INTERNO','["20260930"]','Filtros por rango pueden usar enteros AAAAMMDD; no aplicar funciones DATE directamente al INTEGER.','CONFIRMADO'),
 ('fact_sdos_captacoloca_m','dominio','VARCHAR(20)','CATEGORIA','Dominio financiero','Dominio de negocio del registro, por ejemplo captacion o colocacion; confirmar codigos exactos.','["captacion","colocacion","familia financiera"]','CAPTACION_COLOCACION','DOMINIO',FALSE,NULL,NULL,NULL,NULL,'Validar valores permitidos y equivalencia con dim_producto.cve_dominio.','INTERNO','[]','No asumir valores exactos ni equivalencia entre catalogos.','PROPUESTO'),

 ('fact_txn_captacoloca_d','num_cta','INT4','IDENTIFICADOR','Numero de cuenta','Cuenta donde se registro el movimiento.','["cuenta","numero de cuenta"]','CUENTAS','CUENTA',FALSE,NULL,NULL,NULL,NULL,'Validar unicidad global o compuesta.','CONFIDENCIAL','[]','No contar cuentas sin DISTINCT.','PROPUESTO'),
 ('fact_txn_captacoloca_d','num_cte','INT4','IDENTIFICADOR','Numero de cliente','Cliente asociado al movimiento.','["cliente","numero de cliente"]','CLIENTES','CLIENTE',FALSE,'FK','dim_cliente','num_cte',NULL,'Validar integridad referencial.','CONFIDENCIAL','[]','Join candidato a dim_cliente, sujeto a cardinalidad.','PROPUESTO'),
 ('fact_txn_captacoloca_d','cve_producto','VARCHAR(40)','IDENTIFICADOR','Clave de producto','Producto financiero asociado al movimiento.','["producto","clave producto"]','PRODUCTOS','PRODUCTO',FALSE,'FK','dim_producto','cve_producto',NULL,'Validar integridad referencial.','INTERNO','[]','Join candidato a dim_producto.','PROPUESTO'),
 ('fact_txn_captacoloca_d','fec_txn','DATE','DATE','Fecha de transaccion','Fecha calendario en que ocurrio el movimiento.','["fecha de movimiento","fecha de operacion","fecha transaccional"]','TIEMPO','FECHA_TRANSACCION',FALSE,NULL,NULL,NULL,NULL,'Formato de fecha ISO YYYY-MM-DD.','INTERNO','[]','Usar para periodificar movimientos; no confundir con fec_informacion.','CONFIRMADO'),
 ('fact_txn_captacoloca_d','cve_mes_txn','INT4','PERIODO','Clave de mes de transaccion','Clave numerica del mes de la transaccion; formato pendiente de confirmar.','["mes de transaccion","periodo de movimiento"]','TIEMPO','MES_TRANSACCION',FALSE,NULL,NULL,NULL,NULL,'Confirmar si formato AAAAMM u otro.','INTERNO','[]','No sustituir fec_txn hasta validar semantica.','PENDIENTE'),
 ('fact_txn_captacoloca_d','saldo_txn','NUMERIC(?)','MONEDA','Importe de transaccion','Importe monetario de cada movimiento (confirmado por el usuario).','["importe","monto","importe del movimiento","monto transaccional"]','TRANSACCIONES','IMPORTE_MOVIMIENTO',FALSE,NULL,NULL,NULL,NULL,'Confirmar precision, escala, moneda y convencion de signo.','FINANCIERO','[]','Puede sumarse por periodo como flujo; no inferir deposito/retiro sin regla de signo o cve_txn.','CONFIRMADO'),
 ('fact_txn_captacoloca_d','cve_txn','INT4','IDENTIFICADOR','Clave de tipo de transaccion','Codigo que identifica el tipo de movimiento.','["tipo de movimiento","codigo de transaccion"]','TRANSACCIONES','TIPO_TRANSACCION',FALSE,'FK','dim_txn','cve_txn',NULL,'Validar unicidad de cve_txn o llave compuesta antes de JOIN.','INTERNO','[]','No unir con dim_txn por cve_txn solamente hasta validar llave.','PENDIENTE'),
 ('fact_txn_captacoloca_d','desc_txn','VARCHAR(40)','TEXTO','Descripcion de transaccion','Descripcion del movimiento almacenada en el hecho.','["descripcion del movimiento","tipo de movimiento"]','TRANSACCIONES','DESCRIPCION_TRANSACCION',FALSE,NULL,NULL,NULL,NULL,'Comparar con dim_txn.desc_txn y definir fuente oficial.','INTERNO','[]','No usar como llave de relacion.','PENDIENTE'),
 ('fact_txn_captacoloca_d','fec_informacion','INTEGER','FECHA','Fecha de informacion','Fecha de corte de la informacion almacenada, representada como entero AAAAMMDD.','["fecha de corte","fecha de informacion","corte de datos"]','TIEMPO','FECHA_CORTE',FALSE,NULL,NULL,NULL,'Convertir a DATE con TO_DATE(fec_informacion::text, ''YYYYMMDD'') cuando se requieran funciones de fecha.','Validar ocho digitos y fecha calendario valida.','INTERNO','["20260930"]','No confundir con fec_txn; filtrar por corte solo cuando la pregunta lo requiera.','CONFIRMADO'),
 ('fact_txn_captacoloca_d','dominio','VARCHAR(20)','CATEGORIA','Dominio financiero','Dominio de negocio del movimiento; confirmar valores y equivalencia con catalogos.','["captacion","colocacion","familia financiera"]','CAPTACION_COLOCACION','DOMINIO',FALSE,NULL,NULL,NULL,NULL,'Validar valores permitidos y equivalencia con dim_producto.cve_dominio.','INTERNO','[]','No asumir equivalencia entre campos sin validar catalogo.','PROPUESTO')
 ) AS v(nombre_tabla,nombre_columna,tipo_dato_fisico,tipo_dato_semantico,nombre_negocio,descripcion_negocio,sinonimos,dominio_negocio,concepto_negocio,es_clave,tipo_clave,tabla_referenciada,campo_referenciado,regla_transformacion,regla_validacion,sensibilidad,ejemplos_valores,sql_generation_hints,nivel_confianza)
)
INSERT INTO semantic.sem_columnas
(tabla_id,nombre_columna,tipo_dato_fisico,tipo_dato_semantico,nombre_negocio,
 descripcion_negocio,sinonimos,dominio_negocio,concepto_negocio,es_clave,tipo_clave,
 tabla_referenciada,campo_referenciado,regla_transformacion,regla_validacion,
 sensibilidad,ejemplos_valores,sql_generation_hints,nivel_confianza)
SELECT t.tabla_id,c.nombre_columna,c.tipo_dato_fisico,c.tipo_dato_semantico,
       c.nombre_negocio,c.descripcion_negocio,c.sinonimos::jsonb,c.dominio_negocio,
       c.concepto_negocio,c.es_clave,c.tipo_clave,c.tabla_referenciada,
       c.campo_referenciado,c.regla_transformacion,c.regla_validacion,
       c.sensibilidad,c.ejemplos_valores::jsonb,c.sql_generation_hints,c.nivel_confianza
FROM c
JOIN semantic.sem_tablas t ON t.nombre_tabla=c.nombre_tabla
ON CONFLICT (tabla_id,nombre_columna) DO UPDATE SET
 tipo_dato_fisico=EXCLUDED.tipo_dato_fisico,
 tipo_dato_semantico=EXCLUDED.tipo_dato_semantico,
 nombre_negocio=EXCLUDED.nombre_negocio,
 descripcion_negocio=EXCLUDED.descripcion_negocio,
 sinonimos=EXCLUDED.sinonimos,
 dominio_negocio=EXCLUDED.dominio_negocio,
 concepto_negocio=EXCLUDED.concepto_negocio,
 es_clave=EXCLUDED.es_clave,
 tipo_clave=EXCLUDED.tipo_clave,
 tabla_referenciada=EXCLUDED.tabla_referenciada,
 campo_referenciado=EXCLUDED.campo_referenciado,
 regla_transformacion=EXCLUDED.regla_transformacion,
 regla_validacion=EXCLUDED.regla_validacion,
 sensibilidad=EXCLUDED.sensibilidad,
 ejemplos_valores=EXCLUDED.ejemplos_valores,
 sql_generation_hints=EXCLUDED.sql_generation_hints,
 nivel_confianza=EXCLUDED.nivel_confianza,
 fecha_actualizacion=CURRENT_TIMESTAMP;
